option.value:
worker_processes  auto;
pid /tmp/nginx.pid;

events {
  worker_connections  1024;
}

http {
  include       /etc/nginx/mime.types;
  default_type  application/octet-stream;
  sendfile      on;
  keepalive_timeout  65;

  gzip on;
  gzip_types text/plain text/css application/javascript application/json image/svg+xml;
  gzip_min_length 1024;

  server {
    listen       8080;
    server_name  _;
    root   /usr/share/nginx/html;
    index  index.html;

    #ngix serving our static frontend file

    resolver 10.43.0.10 valid=10s ipv6=off;

    # Kubernetes liveness/readiness probe endpoint.
    location = /healthz {
      access_log off;
      add_header Content-Type application/json;
      return 200 '{"status":"ok"}';
    }

    # ---- Backend-for-Frontend (BFF) proxy ----
    # The browser calls same-origin /api/auth and /api/payment; nginx forwards
    # them to the internal ClusterIP Services (which serve their payload at "/").
    location = /api/auth {
      set $auth_upstream "auth-service.microservices.svc.cluster.local:3000";
      rewrite ^/api/auth$ / break;
      proxy_pass http://$auth_upstream;
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    location = /api/payment {
      set $payment_upstream "payment-service.microservices.svc.cluster.local:5000";
      rewrite ^/api/payment$ / break;
      proxy_pass http://$payment_upstream;
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Long-cache fingerprinted static assets produced by Vite.
    location /assets/ {
      expires 1y;
      add_header Cache-Control "public, immutable";
      try_files $uri =404;
    }

    # SPA fallback: every other route serves index.html so client-side
    # routing works.
    location / {
      try_files $uri $uri/ /index.html;
    }

    # Basic security headers.
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
  }
}

worker_processes  auto;
pid /tmp/nginx.pid;

events {
  worker_connections  1024;
}

http {
  include       /etc/nginx/mime.types;
  default_type  application/octet-stream;
  sendfile      on;
  keepalive_timeout  65;

  gzip on;
  gzip_types text/plain text/css application/javascript application/json image/svg+xml;
  gzip_min_length 1024;

  server {
    listen       8080;
    server_name  _;
    root   /usr/share/nginx/html;
    index  index.html;

    #ngix serving our static frontend file

    resolver 10.43.0.10 valid=10s ipv6=off;

    # Kubernetes liveness/readiness probe endpoint.
    location = /healthz {
      access_log off;
      add_header Content-Type application/json;
      return 200 '{"status":"ok"}';
    }

    # Scraped by the nginx-prometheus-exporter sidecar from inside the pod only.
    location = /stub_status {
      access_log off;
      allow 127.0.0.1;
      deny all;
      stub_status;
    }

    # ---- Backend-for-Frontend (BFF) proxy ----
    # The browser calls same-origin /api/auth and /api/payment; nginx forwards
    # them to the internal ClusterIP Services (which serve their payload at "/").
    location = /api/auth {
      set $auth_upstream "auth-service.microservices.svc.cluster.local:3000";
      rewrite ^/api/auth$ / break;
      proxy_pass http://$auth_upstream;
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    location = /api/payment {
      set $payment_upstream "payment-service.microservices.svc.cluster.local:5000";
      rewrite ^/api/payment$ / break;
      proxy_pass http://$payment_upstream;
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Long-cache fingerprinted static assets produced by Vite.
    location /assets/ {
      expires 1y;
      add_header Cache-Control "public, immutable";
      try_files $uri =404;
    }

    # SPA fallback: every other route serves index.html so client-side
    # routing works.
    location / {
      try_files $uri $uri/ /index.html;
    }

    # Basic security headers.
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
  }
}

# Helm values for kube-prometheus-stack (referenced by argocd/kube-prometheus-stack.application.yaml)
# k3s bundles these control-plane components into one process and does not expose # their metrics endpoints, so scraping them would only create false "down" alerts. kubeEtcd: enabled: false kubeScheduler: enabled: false kubeControllerManager: enabled: false kubeProxy: enabled: false
prometheus: prometheusSpec: # Pick up ServiceMonitors / PodMonitors / PrometheusRules from every namespace, # not only those labelled with this Helm release. serviceMonitorSelectorNilUsesHelmValues: false podMonitorSelectorNilUsesHelmValues: false ruleSelectorNilUsesHelmValues: false probeSelectorNilUsesHelmValues: false retention: 7d resources: requests: { cpu: 200m, memory: 512Mi } limits: { memory: 1Gi } storageSpec: volumeClaimTemplate: spec: storageClassName: local-path accessModes: ["ReadWriteOnce"] resources: requests: storage: 10Gi
alertmanager: alertmanagerSpec: # Full Alertmanager config (SMTP credentials) lives in this SealedSecret-managed Secret. configSecret: alertmanager-kps-config resources: requests: { cpu: 20m, memory: 64Mi } limits: { memory: 128Mi }
grafana: admin: existingSecret: grafana-admin userKey: admin-user passwordKey: admin-password # Dashboards in ConfigMaps labelled grafana_dashboard=1 (any namespace) are auto-loaded. sidecar: dashboards: enabled: true label: grafana_dashboard labelValue: "1" searchNamespace: ALL service: type: ClusterIP # access with: kubectl -n monitoring port-forward svc/kps-grafana 3000:80 resources: requests: { cpu: 50m, memory: 128Mi } limits: { memory: 256Mi }
kube-state-metrics: resources: requests: { cpu: 10m, memory: 32Mi } limits: { memory: 128Mi }
prometheus-node-exporter: resources: requests: { cpu: 10m, memory: 16Mi } limits: { memory: 64Mi }
prometheusOperator: resources: requests: { cpu: 50m, memory: 64Mi } limits: { memory: 256Mi }

# Helm values for kube-prometheus-stack (referenced by argocd/kube-prometheus-stack.application.yaml)
# k3s bundles these control-plane components into one process and does not expose # their metrics endpoints, so scraping them would only create false "down" alerts. kubeEtcd: enabled: false kubeScheduler: enabled: false kubeControllerManager: enabled: false kubeProxy: enabled: false
prometheus: prometheusSpec: # Pick up ServiceMonitors / PodMonitors / PrometheusRules from every namespace, # not only those labelled with this Helm release. serviceMonitorSelectorNilUsesHelmValues: false podMonitorSelectorNilUsesHelmValues: false ruleSelectorNilUsesHelmValues: false probeSelectorNilUsesHelmValues: false retention: 7d resources: requests: { cpu: 200m, memory: 512Mi } limits: { memory: 1Gi } storageSpec: volumeClaimTemplate: spec: storageClassName: local-path accessModes: ["ReadWriteOnce"] resources: requests: storage: 10Gi
alertmanager: alertmanagerSpec: # Full Alertmanager config (SMTP credentials) lives in this SealedSecret-managed Secret. configSecret: alertmanager-kps-config resources: requests: { cpu: 20m, memory: 64Mi } limits: { memory: 128Mi }
grafana: admin: existingSecret: grafana-admin userKey: admin-user passwordKey: admin-password # Dashboards in ConfigMaps labelled grafana_dashboard=1 (any namespace) are auto-loaded. sidecar: dashboards: enabled: true label: grafana_dashboard labelValue: "1" searchNamespace: ALL service: type: ClusterIP # access with: kubectl -n monitoring port-forward svc/kps-grafana 3000:80 # Grafana 13 uses ~250Mi at startup (was OOM-killed at 256Mi), so give it headroom. resources: requests: { cpu: 100m, memory: 256Mi } limits: { memory: 768Mi } # Skip the background download of preinstalled apps (loki/pyroscope/advisor...) # we don't use; saves startup memory and needs no internet access. grafana.ini: plugins: preinstall_disabled: true preinstall_auto_update: false
kube-state-metrics: resources: requests: { cpu: 10m, memory: 32Mi } limits: { memory: 128Mi }
prometheus-node-exporter: resources: requests: { cpu: 10m, memory: 16Mi } limits: { memory: 64Mi }
prometheusOperator: resources: requests: { cpu: 50m, memory: 64Mi } limits: { memory: 256Mi }
